Audit these two Vanilla JS WebMCP tools registered on `document.modelContext`:

```js
const currencyCtrl = new AbortController();
await document.modelContext.registerTool(
  {
    name: 'list_supported_currencies',
    description: 'Lists ISO billing currencies supported by the store. Use when the user asks which currencies are accepted or before switching display pricing.',
    inputSchema: { type: 'object', properties: {} },
    outputSchema: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          code: { type: 'string', description: 'ISO 4217 currency code' },
          symbol: { type: 'string', description: 'Currency symbol' }
        },
        required: ['code', 'symbol']
      }
    },
    annotations: { readOnlyHint: true },
    async execute(_args, { signal }) {
      const res = await fetch('/api/billing/currencies', { signal });
      if (!res.ok) {
        return { error: 'Currency list unavailable.', code: 'UNAVAILABLE', retryable: true };
      }
      return await res.json(); // [{ code: 'USD', symbol: '$' }, ...]
    }
  },
  { signal: currencyCtrl.signal }
);

await document.modelContext.registerTool({
  name: 'list_issue_comments',
  description: 'Lists comments posted by users on an issue. Use when the user wants to read discussion threads on a specific issue.',
  inputSchema: {
    type: 'object',
    properties: { issue_id: { type: 'string', description: 'Issue identifier' } },
    required: ['issue_id']
  },
  outputSchema: {
    type: 'object',
    properties: {
      total_count: { type: 'integer' },
      comments: {
        type: 'array',
        items: {
          type: 'object',
          properties: { author: { type: 'string' }, body: { type: 'string' } },
          required: ['author', 'body']
        }
      }
    },
    required: ['total_count', 'comments']
  },
  annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true },
  async execute({ issue_id }, { signal }) {
    const res = await fetch(`/api/issues/${encodeURIComponent(issue_id)}/comments`, { signal });
    if (!res.ok) throw new Error('Issue not found');
    const data = await res.json();
    return {
      structuredContent: { total_count: data.total, comments: data.items },
      content: [{ type: 'text', text: JSON.stringify(data.items) }]
    };
  }
});
```
